{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "RadioListItem",
    "subComponentOf": "RadioList",
    "displayName": "Radio List Item",
    "isHiddenFromOverview": true,
    "description": "Individual radio item with label, description, and content slots. Under a coarse pointer an enabled option’s target grows toward 44 px through an invisible hit area. It never shrinks below the row and stops at half the gap to a closer neighbour; the row keeps its size. That hit area is the row’s `::after`, so decorate a row with a child.",
    "playground": {
      "defaults": {
        "value": "option-1",
        "label": "Option"
      },
      "wrapper": {
        "component": "RadioList",
        "props": {
          "value": "option-1",
          "label": "Radio list"
        }
      }
    },
    "props": [
      {
        "name": "label",
        "type": "ReactNode",
        "description": "Primary label for the radio item. Rich labels may contain links or buttons, which keep their own behavior without selecting the item. The label text names the radio; use aria-label only when that text is absent, or retain every visible label word in the override.",
        "required": true
      },
      {
        "name": "aria-label",
        "type": "string",
        "description": "Plain-text accessible name for the radio, applied to the control rather than the row. It overrides the name derived from the label. Use it when a rich label has no visible text; otherwise retain every visible label word."
      },
      {
        "name": "value",
        "type": "string",
        "description": "Value of this radio item.",
        "required": true
      },
      {
        "name": "description",
        "type": "ReactNode",
        "description": "Secondary content displayed below the label. Links and buttons keep their own click behaviour — the row only delegates clicks from its non-interactive surface to the radio."
      },
      {
        "name": "align",
        "type": "'center' | 'start' | 'first-line'",
        "description": "Vertical alignment of the start and end content against the label, passed through to Item unchanged. `first-line` keeps a small mark (a radio) level with the first line of a wrapped label. See Item.align.",
        "default": "'center'"
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Whether this individual radio item is disabled.",
        "default": "false"
      },
      {
        "name": "startContent",
        "type": "ReactNode",
        "description": "Content to render before the radio circle.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "check",
              "size": "sm"
            }
          }
        ]
      },
      {
        "name": "endContent",
        "type": "ReactNode",
        "description": "Content to render after the label.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "chevronDown",
              "size": "sm"
            }
          },
          {
            "__element": "Badge",
            "props": {
              "label": "3"
            }
          }
        ]
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/RadioList",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
